def thanos_sort(n, arr):
    def sorted_length(start, end):
        # Check if a subarray arr[start:end] is sorted
        for i in range(start, end - 1):
            if arr[i] > arr[i + 1]:
                return 0
        return end - start

    def max_sorted_length(left, right):
        if left >= right:
            return 0
        if left + 1 == right:
            return 1

        mid = (left + right) // 2

        # Calculate the maximum sorted length by trying to remove either the left or right half
        left_half_sorted = sorted_length(left, mid)
        right_half_sorted = sorted_length(mid, right)

        # Compare the lengths obtained by removing each half
        return max(left_half_sorted, right_half_sorted)

    return max_sorted_length(0, n)


